-- Canonical Match Report competition keys, GW001-GW010.
-- Preserve existing player/minute normalization and Site projection triggers.
-- Country is used only by domestic multi-world competitions, matching current Results.
-- Division is used only by league and playoff.
-- Execute via Database Manager plan_migration / execute_migration in the stated target.

-- Target: custom
CREATE TRIGGER imc_mr_key_gw001_bi BEFORE INSERT ON `GW001_IMC Match Report` FOR EACH ROW SET NEW.competition_key = CASE WHEN UPPER(NEW.competition_group) IN ('DOMESTIC','INTERNATIONAL','NATIONS') AND NEW.sm_action REGEXP '^[A-Za-z]+$' AND (LOWER(NEW.sm_action) NOT IN ('league','playoff') OR NEW.sm_division REGEXP '^[0-9]+$')  THEN CONCAT(NEW.game_world_id,'','|',UPPER(NEW.competition_group),'|',LOWER(NEW.sm_action),IF(LOWER(NEW.sm_action) IN ('league','playoff'),CONCAT('|',NEW.sm_division),'')) ELSE NEW.competition_key END;
